1	package reconcore
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"math/big"
8		"strconv"
9		"strings"
10		"time"
11	)
12	
13	const (
14		// dateLayout is the only accepted date format.
15		dateLayout = "2006-01-02"
16	
17		// maxAmountMinor bounds every monetary value so that conversions stay
18		// exactly representable in int64 arithmetic.
19		maxAmountMinor = int64(1_000_000_000_000_000)
20	
21		maxIdentifierLength = 128
22		maxTextLength       = 256
23		maxRateDigits       = 18
24		maxRateDecimals     = 9
25	)
26	
27	// normalBalanceByType maps an account type onto the side that increases it.
28	var normalBalanceByType = map[string]string{
29		"asset":     "debit",
30		"expense":   "debit",
31		"liability": "credit",
32		"equity":    "credit",
33		"revenue":   "credit",
34	}
35	
36	// Rate is an immutable exchange rate snapshot: one unit of Base is worth Rate
37	// units of Quote from Date onwards. The decimal string is stored together with
38	// its exact reduced fraction so nothing is ever recomputed from a float.
39	type Rate struct {
40		Base        string `json:"base"`
41		Quote       string `json:"quote"`
42		Date        string `json:"date"`
43		Rate        string `json:"rate"`
44		Numerator   int64  `json:"numerator"`
45		Denominator int64  `json:"denominator"`
46		CreatedAt   string `json:"created_at"`
47	}
48	
49	// IdempotencyRecord stores the first response produced for a key.
50	type IdempotencyRecord struct {
51		Key       string `json:"key"`
52		Operation string `json:"operation"`
53		Response  string `json:"response"`
54		CreatedAt string `json:"created_at"`
55	}
56	
57	// Account is one node of the chart of accounts. Every account holds exactly one
58	// currency.
59	type Account struct {
60		ID            string  `json:"id"`
61		Name          string  `json:"name"`
62		Type          string  `json:"type"`
63		ParentID      *string `json:"parent_id"`
64		Currency      string  `json:"currency"`
65		NormalBalance string  `json:"normal_balance"`
66		CreatedAt     string  `json:"created_at"`
67	}
68	
69	// AccountNode is an Account with its subtree attached.
70	type AccountNode struct {
71		Account
72		Children []*AccountNode `json:"children"`
73	}
74	
75	// JournalLine is one balanced-verified posting. AmountMinor is expressed in the
76	// line currency; FunctionalAmountMinor is the same amount converted into the
77	// functional currency with the resolved rate.
78	type JournalLine struct {
79		Index                 int    `json:"index"`
80		AccountID             string `json:"account_id"`
81		Side                  string `json:"side"`
82		AmountMinor           int64  `json:"amount_minor"`
83		Currency              string `json:"currency"`
84		Rate                  string `json:"rate"`
85		RateNumerator         int64  `json:"rate_numerator"`
86		RateDenominator       int64  `json:"rate_denominator"`
87		RateSource            string `json:"rate_source"`
88		FunctionalAmountMinor int64  `json:"functional_amount_minor"`
89		Reference             string `json:"reference,omitempty"`
90	}
91	
92	// Journal is an immutable, balanced voucher.
93	type Journal struct {
94		ID                    string         `json:"id"`
95		Date                  string         `json:"date"`
96		Memo                  string         `json:"memo,omitempty"`
97		FunctionalCurrency    string         `json:"functional_currency"`
98		Lines                 []*JournalLine `json:"lines"`
99		DebitFunctionalMinor  int64          `json:"debit_functional_minor"`
100		CreditFunctionalMinor int64          `json:"credit_functional_minor"`
101		CreatedAt             string         `json:"created_at"`
102	}
103	
104	// Period is an inclusive date window.
105	type Period struct {
106		Start string `json:"start"`
107		End   string `json:"end"`
108	}
109	
110	// PeriodClose freezes one calendar month. Once a close exists, ordinary
111	// journals dated inside the period are rejected and only adjustment journals
112	// posted through the close itself are appended to it.
113	type PeriodClose struct {
114		ID                   string   `json:"id"`
115		Period               Period   `json:"period"`
116		Status               string   `json:"status"`
117		ClosedAt             string   `json:"closed_at"`
118		AdjustmentCount      int      `json:"adjustment_count"`
119		AdjustmentJournalIDs []string `json:"adjustment_journal_ids"`
120	}
121	
122	// StatementLine is one bank statement line. AmountMinor is signed: positive
123	// means money into the account (a debit to it), negative means money out.
124	type StatementLine struct {
125		ID          string `json:"id"`
126		Date        string `json:"date"`
127		AmountMinor int64  `json:"amount_minor"`
128		Reference   string `json:"reference,omitempty"`
129		Description string `json:"description,omitempty"`
130	}
131	
132	// Statement is an imported bank statement for one account.
133	type Statement struct {
134		ID                  string           `json:"id"`
135		AccountID           string           `json:"account_id"`
136		Currency            string           `json:"currency"`
137		Period              Period           `json:"period"`
138		OpeningBalanceMinor int64            `json:"opening_balance_minor"`
139		ClosingBalanceMinor int64            `json:"closing_balance_minor"`
140		Lines               []*StatementLine `json:"lines"`
141		CreatedAt           string           `json:"created_at"`
142	}
143	
144	// Difference is one classified reconciliation difference. Exactly one statement
145	// line and/or ledger line is referenced, never both buckets for the same line.
146	type Difference struct {
147		Type                 string `json:"type"`
148		Detail               string `json:"detail"`
149		StatementLineID      string `json:"statement_line_id,omitempty"`
150		LedgerLineID         string `json:"ledger_line_id,omitempty"`
151		StatementDate        string `json:"statement_date,omitempty"`
152		LedgerDate           string `json:"ledger_date,omitempty"`
153		StatementAmountMinor *int64 `json:"statement_amount_minor,omitempty"`
154		LedgerAmountMinor    *int64 `json:"ledger_amount_minor,omitempty"`
155		DifferenceMinor      int64  `json:"difference_minor"`
156	}
157	
158	// DifferenceSummary counts the four mutually exclusive difference categories.
159	type DifferenceSummary struct {
160		Timing             int `json:"timing"`
161		AmountMismatch     int `json:"amount_mismatch"`
162		MissingInLedger    int `json:"missing_in_ledger"`
163		MissingInStatement int `json:"missing_in_statement"`
164	}
165	
166	// Reconciliation is the frozen outcome of matching one statement against the
167	// ledger activity of its account inside its period.
168	type Reconciliation struct {
169		ID                 string            `json:"id"`
170		StatementID        string            `json:"statement_id"`
171		AccountID          string            `json:"account_id"`
172		Currency           string            `json:"currency"`
173		FunctionalCurrency string            `json:"functional_currency"`
174		Period             Period            `json:"period"`
175		Status             string            `json:"status"`
176		MatchedCount       int               `json:"matched_count"`
177		StatementLineCount int               `json:"statement_line_count"`
178		LedgerLineCount    int               `json:"ledger_line_count"`
179		StatementNetMinor  int64             `json:"statement_net_minor"`
