1	package reconcore
2	
3	import (
4		"fmt"
5		"sort"
6		"time"
7	)
8	
9	// Service implements the ReconCore contract on top of a Store. The functional
10	// currency is fixed for the lifetime of the process and is the unit every
11	// journal is balanced in.
12	type Service struct {
13		store              *Store
14		functionalCurrency string
15		clock              func() time.Time
16	}
17	
18	// NewService wires a store, a functional currency and an injectable clock.
19	func NewService(store *Store, functionalCurrency string, clock func() time.Time) (*Service, error) {
20		if store == nil {
21			return nil, InternalError("service requires a store")
22		}
23		code, err := validateCurrency(functionalCurrency, "functional currency", true)
24		if err != nil {
25			return nil, err
26		}
27		if clock == nil {
28			clock = time.Now
29		}
30		return &Service{store: store, functionalCurrency: code, clock: clock}, nil
31	}
32	
33	// FunctionalCurrency reports the reporting currency of this process.
34	func (s *Service) FunctionalCurrency() string { return s.functionalCurrency }
35	
36	func (s *Service) now() string {
37		return s.clock().UTC().Format("2006-01-02T15:04:05Z")
38	}
39	
40	// runIdempotent executes action at most once per key. The first response is
41	// stored and replayed for every later request that carries the same key.
42	func (s *Service) runIdempotent(key, operation string, action func(state *State) (any, error)) (any, error) {
43		if key == "" {
44			return nil, ValidationError("Idempotency-Key header is required")
45		}
46		if len(key) > 200 {
47			return nil, ValidationError("Idempotency-Key must be at most 200 characters")
48		}
49		var response any
50		err := s.store.Update(func(state *State) error {
51			if record, found := state.Idempotency[key]; found {
52				if record.Operation != operation {
53					return ConflictError("idempotency key was already used for another operation")
54				}
55				stored, err := decodeResponse(record.Response)
56				if err != nil {
57					return err
58				}
59				response = stored
60				return nil
61			}
62			value, err := action(state)
63			if err != nil {
64				return err
65			}
66			normalized, err := normalizeResponse(value)
67			if err != nil {
68				return err
69			}
70			encoded, err := encodeResponse(normalized)
71			if err != nil {
72				return err
73			}
74			state.Idempotency[key] = &IdempotencyRecord{
75				Key:       key,
76				Operation: operation,
77				Response:  encoded,
78				CreatedAt: s.now(),
79			}
80			response = normalized
81			return nil
82		})
83		if err != nil {
84			return nil, err
85		}
86		return response, nil
87	}
