194	func (s *Service) computeBalance(state *State, account *Account, asOf string) *Balance {
195		balance := &Balance{
196			AccountID:          account.ID,
197			AccountName:        account.Name,
198			AccountType:        account.Type,
199			NormalBalance:      account.NormalBalance,
200			Currency:           account.Currency,
201			FunctionalCurrency: s.functionalCurrency,
202			AsOf:               asOf,
203		}
204		for _, journal := range sortedJournals(state) {
205			if journal.Date > asOf {
206				continue
207			}
208			for _, line := range journal.Lines {
209				if line.AccountID != account.ID {
210					continue
211				}
212				balance.PostingCount++
213				if line.Side == "debit" {
214					balance.DebitMinor += line.AmountMinor
215					balance.FunctionalDebitMinor += line.FunctionalAmountMinor
216				} else {
217					balance.CreditMinor += line.AmountMinor
218					balance.FunctionalCreditMinor += line.FunctionalAmountMinor
219				}
220				if balance.FirstPostingDate == "" || journal.Date < balance.FirstPostingDate {
221					balance.FirstPostingDate = journal.Date
222				}
223				if journal.Date > balance.LastPostingDate {
224					balance.LastPostingDate = journal.Date
225				}
226			}
227		}
228		balance.NetMinor = balance.DebitMinor - balance.CreditMinor
229		balance.FunctionalNetMinor = balance.FunctionalDebitMinor - balance.FunctionalCreditMinor
230		balance.BalanceMinor = balance.NetMinor
231		if account.NormalBalance == "credit" {
232			balance.BalanceMinor = -balance.NetMinor
233		}
234		return balance
235	}
