312	// CreateJournal posts an immutable voucher once it balances in the functional
313	// currency. A date inside a closed period is rejected.
314	func (s *Service) CreateJournal(body []byte, key string) (any, error) {
315		var request createJournalRequest
316		if err := decodeObject(body, &request); err != nil {
317			return nil, err
318		}
319		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
320		if err != nil {
321			return nil, err
322		}
323		return s.runIdempotent(key, "create-journal:"+id, func(state *State) (any, error) {
324			if _, found := state.Journals[id]; found {
325				return nil, ConflictError("journal %s already exists", id)
326			}
327			if closedPeriodFor(state, date) != nil {
328				return nil, ConflictError("closed period rejects journal")
329			}
330			journal, err := s.buildJournal(state, &request, id, date, memo)
331			if err != nil {
332				return nil, err
333			}
334			state.Journals[id] = journal
335			return journal, nil
336		})
337	}
