339	// validateJournalHead checks the journal fields that do not depend on the
340	// stored state and returns them normalized.
341	func validateJournalHead(rawID, rawDate, rawMemo string, lineCount int) (string, string, string, error) {
342		id, err := validateIdentifier(rawID, "journal id")
343		if err != nil {
344			return "", "", "", err
345		}
346		date, err := validateDate(rawDate, "date")
347		if err != nil {
348			return "", "", "", err
349		}
350		memo, err := validateText(rawMemo, "memo")
351		if err != nil {
352			return "", "", "", err
353		}
354		if lineCount < 2 {
355			return "", "", "", ValidationError("lines must contain at least two postings")
356		}
357		return id, date, memo, nil
358	}
359	
360	// buildJournal resolves every line and freezes the balanced voucher. The
361	// caller owns the duplicate-id and closed-period policy.
362	func (s *Service) buildJournal(state *State, request *createJournalRequest, id, date, memo string) (*Journal, error) {
363		journal := &Journal{
364			ID:                 id,
365			Date:               date,
366			Memo:               memo,
367			FunctionalCurrency: s.functionalCurrency,
368			Lines:              []*JournalLine{},
369			CreatedAt:          s.now(),
370		}
371		var debits, credits int64
372		for position, raw := range request.Lines {
373			line, err := s.buildJournalLine(state, raw, position+1, date)
374			if err != nil {
375				return nil, err
376			}
377			if line.Side == "debit" {
378				debits += line.FunctionalAmountMinor
379			} else {
380				credits += line.FunctionalAmountMinor
381			}
382			journal.Lines = append(journal.Lines, line)
383		}
384		if debits != credits {
385			return nil, ValidationError(
386				"journal is not balanced in %s: debits %d, credits %d",
387				s.functionalCurrency, debits, credits,
388			)
389		}
390		journal.DebitFunctionalMinor = debits
391		journal.CreditFunctionalMinor = credits
392		return journal, nil
393	}
