395	// closedPeriodFor returns the close that covers date, or nil when the date
396	// falls in an open period.
397	func closedPeriodFor(state *State, date string) *PeriodClose {
398		for _, close := range state.PeriodCloses {
399			if close.Period.Start <= date && date <= close.Period.End {
400				return close
401			}
402		}
403		return nil
404	}
