422	// CreatePeriodClose freezes one calendar month. The period must be exactly one
423	// natural month and no other close may cover the same month.
424	func (s *Service) CreatePeriodClose(body []byte, key string) (any, error) {
425		var request createPeriodCloseRequest
426		if err := decodeObject(body, &request); err != nil {
427			return nil, err
428		}
429		if _, err := validateIdentifier(request.ID, "period close id"); err != nil {
430			return nil, ValidationError("invalid period close id")
431		}
432		id := request.ID
433		start, err := validatePeriodCloseDate(request.Period.Start)
434		if err != nil {
435			return nil, err
436		}
437		end, err := validatePeriodCloseDate(request.Period.End)
438		if err != nil {
439			return nil, err
440		}
441		if !isCalendarMonth(start, end) {
442			return nil, ValidationError("period is not one calendar month")
443		}
444		return s.runIdempotent(key, "create-period-close:"+id, func(state *State) (any, error) {
445			if _, found := state.PeriodCloses[id]; found {
446				return nil, ConflictError("period close exists")
447			}
448			for _, existing := range state.PeriodCloses {
449				if existing.Period.Start[:7] == start[:7] {
450					return nil, ConflictError("calendar month is closed")
451				}
452			}
453			close := &PeriodClose{
454				ID:                   id,
455				Period:               Period{Start: start, End: end},
456				Status:               "closed",
457				ClosedAt:             s.now(),
458				AdjustmentCount:      0,
459				AdjustmentJournalIDs: []string{},
460			}
461			state.PeriodCloses[id] = close
462			return close, nil
463		})
464	}
465	
466	// validatePeriodCloseDate applies the public YYYY-MM-DD rule under the period
467	// close message.
468	func validatePeriodCloseDate(value string) (string, error) {
469		if _, err := validateDate(value, "period date"); err != nil {
470			return "", ValidationError("invalid period date")
471		}
472		return value, nil
473	}
474	
475	// isCalendarMonth reports whether start and end together span exactly one
476	// natural month, first day to last day.
477	func isCalendarMonth(start, end string) bool {
478		first, err := time.Parse(dateLayout, start)
479		if err != nil || first.Day() != 1 {
480			return false
481		}
482		last, err := time.Parse(dateLayout, end)
483		if err != nil {
484			return false
485		}
486		return last.Equal(first.AddDate(0, 1, -1))
487	}
