500	// CreateAdjustment posts an adjustment journal into a closed period through
501	// its close. The voucher follows every ordinary journal rule and additionally
502	// requires a memo and a date inside the closed period.
503	func (s *Service) CreateAdjustment(closeID string, body []byte, key string) (any, error) {
504		var request createJournalRequest
505		if err := decodeObject(body, &request); err != nil {
506			return nil, err
507		}
508		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
509		if err != nil {
510			return nil, err
511		}
512		return s.runIdempotent(key, "create-adjustment:"+closeID+":"+id, func(state *State) (any, error) {
513			close, found := state.PeriodCloses[closeID]
514			if !found {
515				return nil, NotFoundError("period close not found")
516			}
517			if memo == "" {
518				return nil, ValidationError("adjustment memo required")
519			}
520			if date < close.Period.Start || date > close.Period.End {
521				return nil, ValidationError("adjustment date outside period")
522			}
523			if _, found := state.Journals[id]; found {
524				return nil, ConflictError("journal exists")
525			}
526			journal, err := s.buildJournal(state, &request, id, date, memo)
527			if err != nil {
528				return nil, err
529			}
530			state.Journals[id] = journal
531			close.AdjustmentJournalIDs = append(close.AdjustmentJournalIDs, id)
532			close.AdjustmentCount = len(close.AdjustmentJournalIDs)
533			return journal, nil
534		})
535	}
