537	func (s *Service) buildJournalLine(state *State, raw *journalLineRequest, index int, date string) (*JournalLine, error) {
538		if raw == nil {
539			return nil, ValidationError("lines[%d] must be an object", index)
540		}
541		accountID, err := validateIdentifier(raw.AccountID, fmt.Sprintf("lines[%d].account_id", index))
542		if err != nil {
543			return nil, err
544		}
545		account, found := state.Accounts[accountID]
546		if !found {
547			return nil, ValidationError("lines[%d].account_id %s does not exist", index, accountID)
548		}
549		if raw.Side != "debit" && raw.Side != "credit" {
550			return nil, ValidationError("lines[%d].side must be debit or credit", index)
551		}
552		amount, err := validateAmount(raw.AmountMinor, fmt.Sprintf("lines[%d].amount_minor", index), false, false)
553		if err != nil {
554			return nil, err
555		}
556		currency, err := validateCurrency(raw.Currency, fmt.Sprintf("lines[%d].currency", index), false)
557		if err != nil {
558			return nil, err
559		}
560		if currency == "" {
561			currency = account.Currency
562		}
563		if currency != account.Currency {
564			return nil, ValidationError(
565				"lines[%d].currency %s must match the currency %s of account %s",
566				index, currency, account.Currency, accountID,
567			)
568		}
569		reference, err := validateText(raw.Reference, fmt.Sprintf("lines[%d].reference", index))
570		if err != nil {
571			return nil, err
572		}
573		numerator, denominator, source, err := s.resolveRate(state, currency, date, raw.Rate, fmt.Sprintf("lines[%d].rate", index))
574		if err != nil {
575			return nil, err
576		}
577		functional, err := convertMinor(amount, numerator, denominator)
578		if err != nil {
579			return nil, err
580		}
581		if functional < 1 {
582			return nil, ValidationError(
583				"lines[%d] converts to zero minor units in %s; use a larger amount or a finer exchange rate",
584				index, s.functionalCurrency,
585			)
586		}
587		return &JournalLine{
588			Index:                 index,
589			AccountID:             accountID,
590			Side:                  raw.Side,
591			AmountMinor:           amount,
592			Currency:              currency,
593			Rate:                  raw.Rate,
594			RateNumerator:         numerator,
595			RateDenominator:       denominator,
596			RateSource:            source,
597			FunctionalAmountMinor: functional,
598			Reference:             reference,
599		}, nil
600	}
601	
602	// resolveRate returns the exact fraction that converts one minor unit of
603	// currency into the functional currency for the given date.
604	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
605		if currency == s.functionalCurrency {
606			if declared == "" || declared == "1" {
607				return 1, 1, "identity", nil
608			}
609			numerator, denominator, err := parseRateFraction(declared, field)
610			if err != nil {
611				return 0, 0, "", err
612			}
613			if numerator != denominator {
614				return 0, 0, "", ValidationError(
615					"%s must be omitted or exactly 1 because %s is the functional currency",
616					field, currency,
617				)
618			}
619			return 1, 1, "identity", nil
620		}
621		if declared != "" {
622			numerator, denominator, err := parseRateFraction(declared, field)
623			if err != nil {
624				return 0, 0, "", err
625			}
626			return numerator, denominator, "declared", nil
627		}
628		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
629			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
630		}
631		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
632			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
633		}
634		return 0, 0, "", ValidationError(
635			"no %s/%s exchange rate snapshot exists on or before %s",
636			currency, s.functionalCurrency, date,
637		)
638	}
