694			return nil, err
695		}
696		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
697		if err != nil {
698			return nil, err
699		}
700		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
701			if _, found := state.Statements[id]; found {
702				return nil, ConflictError("statement %s already exists", id)
703			}
704			account, found := state.Accounts[accountID]
705			if !found {
706				return nil, ValidationError("account_id %s does not exist", accountID)
707			}
708			if currency == "" {
709				currency = account.Currency
710			}
711			if currency != account.Currency {
712				return nil, ValidationError(
713					"currency %s must match the currency %s of account %s",
714					currency, account.Currency, accountID,
715				)
716			}
717			statement := &Statement{
718				ID:                  id,
719				AccountID:           accountID,
720				Currency:            currency,
721				Period:              Period{Start: start, End: end},
722				OpeningBalanceMinor: opening,
723				ClosingBalanceMinor: closing,
724				Lines:               []*StatementLine{},
725				CreatedAt:           s.now(),
726			}
727			total := opening
728			seen := map[string]bool{}
729			for position, raw := range request.Lines {
730				if raw == nil {
731					return nil, ValidationError("lines[%d] must be an object", position+1)
732				}
733				field := fmt.Sprintf("lines[%d]", position+1)
734				lineID, err := validateIdentifier(raw.ID, field+".id")
735				if err != nil {
736					return nil, err
737				}
738				if seen[lineID] {
739					return nil, ValidationError("statement line id %s is duplicated", lineID)
740				}
741				seen[lineID] = true
742				lineDate, err := validateDate(raw.Date, field+".date")
743				if err != nil {
744					return nil, err
745				}
746				if lineDate < start || lineDate > end {
747					return nil, ValidationError("%s.date must fall inside the statement period", field)
748				}
749				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
750				if err != nil {
751					return nil, err
752				}
753				reference, err := validateText(raw.Reference, field+".reference")
754				if err != nil {
755					return nil, err
756				}
757				description, err := validateText(raw.Description, field+".description")
758				if err != nil {
759					return nil, err
760				}
761				total += amount
762				statement.Lines = append(statement.Lines, &StatementLine{
763					ID:          lineID,
764					Date:        lineDate,
765					AmountMinor: amount,
766					Reference:   reference,
767					Description: description,
768				})
769			}
770			if total != closing {
771				return nil, ValidationError(
772					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
773					opening, total-opening, total, closing,
774				)
775			}
776			state.Statements[id] = statement
777			return statement, nil
778		})
779	}
780	
781	// GetStatement returns one imported statement.
782	func (s *Service) GetStatement(id string) (any, error) {
783		return s.store.View(func(state *State) (any, error) {
784			statement, found := state.Statements[id]
785			if !found {
786				return nil, NotFoundError("statement %s was not found", id)
787			}
788			return statement, nil
789		})
790	}
791	
792	type createReconciliationRequest struct {
793		ID          string `json:"id"`
794		StatementID string `json:"statement_id"`
795	}
796	
797	// CreateReconciliation matches one statement against the ledger activity of its
798	// account and freezes the result.
799	func (s *Service) CreateReconciliation(body []byte, key string) (any, error) {
800		var request createReconciliationRequest
801		if err := decodeObject(body, &request); err != nil {
802			return nil, err
803		}
804		id, err := validateIdentifier(request.ID, "reconciliation id")
805		if err != nil {
806			return nil, err
807		}
808		statementID, err := validateIdentifier(request.StatementID, "statement_id")
809		if err != nil {
810			return nil, err
811		}
812		return s.runIdempotent(key, "create-reconciliation:"+id, func(state *State) (any, error) {
813			if _, found := state.Reconciliations[id]; found {
814				return nil, ConflictError("reconciliation %s already exists", id)
815			}
816			statement, found := state.Statements[statementID]
817			if !found {
818				return nil, NotFoundError("statement %s was not found", statementID)
819			}
820			reconciliation, err := s.computeReconciliation(state, statement, id, s.now())
821			if err != nil {
822				return nil, err
823			}
824			state.Reconciliations[id] = reconciliation
825			return reconciliation, nil
826		})
827	}
828	
829	// GetReconciliation returns one stored reconciliation.
830	func (s *Service) GetReconciliation(id string) (any, error) {
831		return s.store.View(func(state *State) (any, error) {
832			reconciliation, found := state.Reconciliations[id]
833			if !found {
834				return nil, NotFoundError("reconciliation %s was not found", id)
835			}
836			return reconciliation, nil
837		})
838	}
839	
840	// ledgerEntry is one journal line seen from the ledger side of a
841	// reconciliation. AmountMinor is signed with debits positive.
842	type ledgerEntry struct {
843		ID          string
844		Date        string
845		AmountMinor int64
846		Reference   string
847	}
848	
849	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
850		entries := []*ledgerEntry{}
851		for _, journal := range sortedJournals(state) {
852			if journal.Date < period.Start || journal.Date > period.End {
853				continue
854			}
855			for _, line := range journal.Lines {
856				if line.AccountID != accountID {
857					continue
858				}
859				amount := line.AmountMinor
860				if line.Side == "credit" {
861					amount = -amount
862				}
863				entries = append(entries, &ledgerEntry{
864					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
865					Date:        journal.Date,
866					AmountMinor: amount,
867					Reference:   line.Reference,
868				})
869			}
870		}
871		return entries
872	}
873	
874	var differenceOrder = map[string]int{
875		"timing":               0,
876		"amount_mismatch":      1,
877		"missing_in_ledger":    2,
878		"missing_in_statement": 3,
879	}
880	
881	// computeReconciliation matches statement lines to ledger lines in three
882	// deterministic tiers and classifies everything that stays unmatched.
883	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
884		lines := make([]*StatementLine, 0, len(statement.Lines))
885		lines = append(lines, statement.Lines...)
886		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
887	
888		entries := ledgerEntries(state, statement.AccountID, statement.Period)
889		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
890	
891		statementUsed := make([]bool, len(lines))
892		ledgerUsed := make([]bool, len(entries))
893		differences := []*Difference{}
894		matched := 0
895		match := func(statementIndex, ledgerIndex int, difference *Difference) {
896			statementUsed[statementIndex] = true
897			ledgerUsed[ledgerIndex] = true
898			matched++
899			if difference != nil {
900				differences = append(differences, difference)
901			}
902		}
903	
904		// Tier 1: same signed amount and same date.
905		for index, line := range lines {
906			for other, entry := range entries {
907				if ledgerUsed[other] {
908					continue
909				}
910				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
911					match(index, other, nil)
912					break
913				}
914			}
915		}
916	
917		// Tier 2: same signed amount, different date, so it only differs in timing.
918		for index, line := range lines {
919			if statementUsed[index] {
920				continue
921			}
922			for other, entry := range entries {
923				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
924					continue
925				}
926				statementAmount := line.AmountMinor
927				ledgerAmount := entry.AmountMinor
928				match(index, other, &Difference{
929					Type:                 "timing",
930					Detail:               "the amounts agree but the ledger date differs from the statement date",
931					StatementLineID:      line.ID,
932					LedgerLineID:         entry.ID,
933					StatementDate:        line.Date,
934					LedgerDate:           entry.Date,
935					StatementAmountMinor: &statementAmount,
936					LedgerAmountMinor:    &ledgerAmount,
937				})
938				break
939			}
940		}
941	
942		// Tier 3: same non-empty reference but a different amount.
943		for index, line := range lines {
944			if statementUsed[index] || line.Reference == "" {
945				continue
946			}
947			for other, entry := range entries {
948				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
949					continue
950				}
951				statementAmount := line.AmountMinor
952				ledgerAmount := entry.AmountMinor
953				match(index, other, &Difference{
954					Type:                 "amount_mismatch",
955					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
956					StatementLineID:      line.ID,
957					LedgerLineID:         entry.ID,
958					StatementDate:        line.Date,
959					LedgerDate:           entry.Date,
960					StatementAmountMinor: &statementAmount,
961					LedgerAmountMinor:    &ledgerAmount,
962					DifferenceMinor:      statementAmount - ledgerAmount,
963				})
964				break
965			}
966		}
967	
968		// Everything still unmatched is missing on one side.
969		for index, line := range lines {
970			if statementUsed[index] {
971				continue
972			}
973			amount := line.AmountMinor
974			differences = append(differences, &Difference{
975				Type:                 "missing_in_ledger",
976				Detail:               "the statement line has no journal line in the period",
977				StatementLineID:      line.ID,
978				StatementDate:        line.Date,
979				StatementAmountMinor: &amount,
980				DifferenceMinor:      amount,
981			})
982		}
983		for index, entry := range entries {
984			if ledgerUsed[index] {
985				continue
986			}
987			amount := entry.AmountMinor
988			differences = append(differences, &Difference{
989				Type:              "missing_in_statement",
990				Detail:            "the journal line has no statement line in the period",
991				LedgerLineID:      entry.ID,
992				LedgerDate:        entry.Date,
993				LedgerAmountMinor: &amount,
994				DifferenceMinor:   -amount,
995			})
996		}
997	
998		sort.SliceStable(differences, func(left, right int) bool {
999			a, b := differences[left], differences[right]
1000			if differenceOrder[a.Type] != differenceOrder[b.Type] {
1001				return differenceOrder[a.Type] < differenceOrder[b.Type]
1002			}
1003			if a.StatementLineID != b.StatementLineID {
1004				return a.StatementLineID < b.StatementLineID
1005			}
1006			return a.LedgerLineID < b.LedgerLineID
1007		})
1008	
1009		var ledgerNet int64
1010		for _, entry := range entries {
1011			ledgerNet += entry.AmountMinor
1012		}
1013		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
1014	
1015		summary := DifferenceSummary{}
1016		var explained int64
1017		for _, difference := range differences {
1018			explained += difference.DifferenceMinor
1019			switch difference.Type {
1020			case "timing":
1021				summary.Timing++
1022			case "amount_mismatch":
1023				summary.AmountMismatch++
1024			case "missing_in_ledger":
1025				summary.MissingInLedger++
1026			case "missing_in_statement":
1027				summary.MissingInStatement++
1028			default:
1029				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
1030			}
1031		}
1032		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
1033			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
1034		}
1035		if explained != statementNet-ledgerNet {
1036			return nil, InternalError("reconciliation differences do not add up to the period difference")
1037		}
1038	
1039		status := "balanced"
1040		if len(differences) > 0 {
1041			status = "differences_found"
1042		}
1043		return &Reconciliation{
1044			ID:                 id,
1045			StatementID:        statement.ID,
1046			AccountID:          statement.AccountID,
1047			Currency:           statement.Currency,
1048			FunctionalCurrency: s.functionalCurrency,
1049			Period:             statement.Period,
1050			Status:             status,
1051			MatchedCount:       matched,
1052			StatementLineCount: len(lines),
1053			LedgerLineCount:    len(entries),
1054			StatementNetMinor:  statementNet,
1055			LedgerNetMinor:     ledgerNet,
1056			DifferenceMinor:    statementNet - ledgerNet,
1057			Summary:            summary,
1058			Differences:        differences,
1059			CreatedAt:          createdAt,
1060		}, nil
1061	}
1062	
1063	func sortedAccounts(state *State) []*Account {
1064		accounts := make([]*Account, 0, len(state.Accounts))
1065		for _, account := range state.Accounts {
1066			accounts = append(accounts, account)
1067		}
1068		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
1069		return accounts
1070	}
1071	
1072	func sortedJournals(state *State) []*Journal {
1073		journals := make([]*Journal, 0, len(state.Journals))
1074		for _, journal := range state.Journals {
1075			journals = append(journals, journal)
1076		}
1077		sort.Slice(journals, func(left, right int) bool {
1078			if journals[left].Date != journals[right].Date {
1079				return journals[left].Date < journals[right].Date
1080			}
1081			return journals[left].ID < journals[right].ID
1082		})
1083		return journals
1084	}
1085	
1086	func sortedRates(state *State) []*Rate {
1087		rates := make([]*Rate, 0, len(state.Rates))
1088		rates = append(rates, state.Rates...)
1089		sort.Slice(rates, func(left, right int) bool {
1090			a, b := rates[left], rates[right]
1091			if a.Base != b.Base {
1092				return a.Base < b.Base
1093			}
1094			if a.Quote != b.Quote {
1095				return a.Quote < b.Quote
1096			}
1097			return a.Date < b.Date
1098		})
1099		return rates
1100	}
1101	
1102	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
1103		nodes := map[string]*AccountNode{}
1104		for _, account := range state.Accounts {
1105			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
1106		}
1107		roots := []*AccountNode{}
1108		for _, account := range sortedAccounts(state) {
1109			node := nodes[account.ID]
1110			if account.ParentID == nil {
1111				roots = append(roots, node)
1112				continue
1113			}
1114			parent, found := nodes[*account.ParentID]
1115			if !found {
1116				roots = append(roots, node)
1117				continue
1118			}
1119			parent.Children = append(parent.Children, node)
1120		}
1121		return nodes, roots
1122	}
1123	
1124	// latestRate returns the most recent snapshot for one direction that is
1125	// effective on the given date.
1126	func latestRate(state *State, base, quote, asOf string) *Rate {
1127		var best *Rate
1128		for _, rate := range state.Rates {
1129			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
1130				continue
1131			}
1132			if best == nil || rate.Date > best.Date {
1133				best = rate
1134			}
1135		}
1136		return best
1137	}
