1	package tests
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"net/http"
10		"net/http/httptest"
11		"path/filepath"
12		"strings"
13		"testing"
14		"time"
15	
16		"reconcore/internal/reconcore"
17	)
18	
19	// fixedClock makes every created_at value reproducible.
20	var fixedClock = time.Date(2024, 6, 1, 12, 0, 0, 0, time.UTC)
21	
22	type request struct {
23		method      string
24		path        string
25		key         string
26		body        string
27		contentType string
28		omitType    bool
29	}
30	
31	type client struct {
32		t      *testing.T
33		server *httptest.Server
34		keys   int
35	}
36	
37	func newClient(t *testing.T) *client {
38		t.Helper()
39		return newClientOn(t, filepath.Join(t.TempDir(), "ledger.db"))
40	}
41	
42	func newClientOn(t *testing.T, database string) *client {
43		t.Helper()
44		store, err := reconcore.OpenStore(database)
45		if err != nil {
46			t.Fatalf("open store: %v", err)
47		}
48		service, err := reconcore.NewService(store, "CNY", func() time.Time { return fixedClock })
49		if err != nil {
50			t.Fatalf("new service: %v", err)
51		}
52		server := httptest.NewServer(reconcore.NewServer(service))
53		t.Cleanup(server.Close)
54		return &client{t: t, server: server}
55	}
56	
57	func (c *client) send(r request) (int, string, map[string]any) {
58		c.t.Helper()
59		var body io.Reader
60		if r.body != "" {
61			body = bytes.NewBufferString(r.body)
62		}
63		httpRequest, err := http.NewRequest(r.method, c.server.URL+r.path, body)
64		if err != nil {
65			c.t.Fatalf("build request: %v", err)
66		}
67		if !r.omitType {
68			contentType := r.contentType
69			if contentType == "" {
70				contentType = "application/json"
71			}
72			httpRequest.Header.Set("Content-Type", contentType)
73		}
74		if r.key != "" {
75			httpRequest.Header.Set("Idempotency-Key", r.key)
76		}
77		response, err := c.server.Client().Do(httpRequest)
78		if err != nil {
79			c.t.Fatalf("%s %s: %v", r.method, r.path, err)
80		}
81		defer response.Body.Close()
82		raw, err := io.ReadAll(response.Body)
83		if err != nil {
84			c.t.Fatalf("read %s %s: %v", r.method, r.path, err)
85		}
86		decoded := map[string]any{}
87		if len(raw) > 0 {
88			if err := json.Unmarshal(raw, &decoded); err != nil {
89				c.t.Fatalf("%s %s returned non-object JSON %s", r.method, r.path, raw)
90			}
91		}
92		return response.StatusCode, string(raw), decoded
93	}
94	
95	func (c *client) post(path, body string) (int, string, map[string]any) {
96		c.keys++
97		return c.send(request{method: http.MethodPost, path: path, key: fmt.Sprintf("key-%03d", c.keys), body: body})
98	}
99	
100	func (c *client) get(path string) (int, string, map[string]any) {
101		return c.send(request{method: http.MethodGet, path: path})
102	}
103	
104	func (c *client) created(path, body string) map[string]any {
105		c.t.Helper()
106		status, raw, decoded := c.post(path, body)
107		if status != http.StatusCreated {
108			c.t.Fatalf("POST %s returned %d: %s", path, status, raw)
109		}
110		return decoded
111	}
112	
113	func (c *client) ok(path string) map[string]any {
114		c.t.Helper()
115		status, raw, decoded := c.get(path)
116		if status != http.StatusOK {
117			c.t.Fatalf("GET %s returned %d: %s", path, status, raw)
118		}
119		return decoded
120	}
121	
122	func (c *client) expect(r request, wantStatus int, wantCode, wantMessage string) {
123		c.t.Helper()
124		status, raw, decoded := c.send(r)
125		if status != wantStatus {
126			c.t.Fatalf("%s %s returned %d (%s), want %d", r.method, r.path, status, raw, wantStatus)
127		}
128		failure, ok := decoded["error"].(map[string]any)
129		if !ok {
130			c.t.Fatalf("%s %s did not return an error body: %s", r.method, r.path, raw)
131		}
132		if failure["code"] != wantCode {
133			c.t.Fatalf("%s %s error code is %v, want %s", r.method, r.path, failure["code"], wantCode)
134		}
135		message, _ := failure["message"].(string)
136		if wantMessage != "" && !strings.Contains(message, wantMessage) {
137			c.t.Fatalf("%s %s message %q does not mention %q", r.method, r.path, message, wantMessage)
138		}
139	}
