145	func integer(t *testing.T, container map[string]any, name string) int64 {
146		t.Helper()
147		raw, found := container[name]
148		if !found {
149			t.Fatalf("field %s is missing in %v", name, container)
150		}
151		value, ok := raw.(float64)
152		if !ok || value != math.Trunc(value) {
153			t.Fatalf("field %s is %v, want an integer", name, raw)
154		}
155		return int64(value)
156	}
