158	func text(t *testing.T, container map[string]any, name string) string {
159		t.Helper()
160		raw, found := container[name]
161		if !found {
162			t.Fatalf("field %s is missing in %v", name, container)
163		}
164		value, ok := raw.(string)
165		if !ok {
166			t.Fatalf("field %s is %v, want a string", name, raw)
167		}
168		return value
169	}
170	
171	func objects(t *testing.T, container map[string]any, name string) []map[string]any {
172		t.Helper()
173		raw, found := container[name]
174		if !found {
175			t.Fatalf("field %s is missing in %v", name, container)
176		}
177		items, ok := raw.([]any)
178		if !ok {
179			t.Fatalf("field %s is %v, want an array", name, raw)
180		}
181		out := make([]map[string]any, 0, len(items))
182		for index, item := range items {
183			entry, ok := item.(map[string]any)
184			if !ok {
185				t.Fatalf("%s[%d] is %v, want an object", name, index, item)
186			}
187			out = append(out, entry)
188		}
189		return out
190	}
