592		if integer(t, reconciliation, "statement_net_minor") != 87000 || integer(t, reconciliation, "ledger_net_minor") != 63000 {
593			t.Fatalf("nets are %v", reconciliation)
594		}
595		if integer(t, reconciliation, "difference_minor") != 24000 {
596			t.Fatalf("difference is %v", reconciliation["difference_minor"])
597		}
598		summary, ok := reconciliation["summary"].(map[string]any)
599		if !ok {
600			t.Fatalf("summary is %v", reconciliation["summary"])
601		}
602		for name, want := range map[string]int64{
603			"timing": 1, "amount_mismatch": 1, "missing_in_ledger": 1, "missing_in_statement": 1,
604		} {
605			if integer(t, summary, name) != want {
606				t.Fatalf("summary.%s is %v, want %d", name, summary[name], want)
607			}
608		}
609	
610		differences := objects(t, reconciliation, "differences")
611		wantTypes := []string{"timing", "amount_mismatch", "missing_in_ledger", "missing_in_statement"}
612		if len(differences) != len(wantTypes) {
613			t.Fatalf("expected four differences, got %v", differences)
614		}
615		var explained int64
616		for index, difference := range differences {
617			if text(t, difference, "type") != wantTypes[index] {
618				t.Fatalf("difference %d is %v, want %s", index, difference["type"], wantTypes[index])
619			}
620			explained += integer(t, difference, "difference_minor")
621		}
622		if explained != integer(t, reconciliation, "difference_minor") {
623			t.Fatalf("differences explain %d but the period difference is %v", explained, reconciliation["difference_minor"])
624		}
625		if text(t, differences[0], "statement_line_id") != "s2" || text(t, differences[0], "ledger_line_id") != "jv-2#1" {
626			t.Fatalf("timing pair is %v", differences[0])
627		}
628		if integer(t, differences[1], "difference_minor") != 5000 {
629			t.Fatalf("amount mismatch is %v", differences[1])
630		}
631		// A ledger line with no statement line contributes its statement-side
632		// equivalent, so a missing credit of 12000 shows up as +12000.
633		if integer(t, differences[3], "difference_minor") != 12000 {
634			t.Fatalf("missing_in_statement is %v", differences[3])
635		}
636		if integer(t, differences[3], "ledger_amount_minor") != -12000 {
637			t.Fatalf("missing_in_statement ledger amount is %v", differences[3])
638		}
639	
640		// A frozen reconciliation is durable and readable.
641		stored := client.ok("/reconciliations/rec-1")
642		if integer(t, stored, "difference_minor") != 24000 || len(objects(t, stored, "differences")) != 4 {
643			t.Fatalf("stored reconciliation is %v", stored)
644		}
645		client.expect(request{method: http.MethodGet, path: "/reconciliations/rec-9"}, 404, "not_found", "")
646	
647		balance := client.ok("/accounts/1100/balance?as_of=2024-03-31")
648		if integer(t, balance, "debit_minor") != 125000 || integer(t, balance, "credit_minor") != 62000 {
649			t.Fatalf("ledger balance is %v", balance)
650		}
651		if integer(t, balance, "net_minor") != integer(t, reconciliation, "ledger_net_minor") {
652			t.Fatalf("ledger net %v disagrees with the balance %v", reconciliation["ledger_net_minor"], balance["net_minor"])
653		}
654	
655		// A fully matched statement reports balanced with no differences.
656		client.created("/accounts", accountBody("1200", "Savings", "asset", "CNY"))
657		client.created("/journals", `{
658			"id":"jv-6","date":"2024-05-04",
659			"lines":[
660				{"account_id":"1200","side":"debit","amount_minor":40000,"reference":"T-1"},
661				{"account_id":"4000","side":"credit","amount_minor":40000,"reference":"T-1"}
662			]}`)
663		client.created("/statements", `{
664			"id":"st-2","account_id":"1200","currency":"CNY",
665			"period":{"start":"2024-05-01","end":"2024-05-31"},
666			"opening_balance_minor":0,"closing_balance_minor":40000,
667			"lines":[{"id":"s1","date":"2024-05-04","amount_minor":40000,"reference":"T-1"}]}`)
668		balanced := client.created("/reconciliations", `{"id":"rec-2","statement_id":"st-2"}`)
669		if text(t, balanced, "status") != "balanced" || integer(t, balanced, "difference_minor") != 0 {
670			t.Fatalf("balanced reconciliation is %v", balanced)
671		}
672		if len(objects(t, balanced, "differences")) != 0 {
673			t.Fatalf("balanced reconciliation has differences: %v", balanced["differences"])
674		}
675		if integer(t, balanced, "matched_count") != 1 {
676			t.Fatalf("balanced reconciliation matched %v", balanced["matched_count"])
677		}
678	}
